from typing import Literal, TypedDict
from langgraph.graph import StateGraph, START, END

class Ticket(TypedDict):
    text: str
    team: str

def sort_ticket(state: Ticket):
    if "환불" in state["text"]:
        return {"team": "billing"}
    if "배송" in state["text"]:
        return {"team": "shipping"}
    return {"team": "general"}

def pick_team(state: Ticket) -> Literal["billing", "shipping", "general"]:
    return state["team"]

g = StateGraph(Ticket)
g.add_node("sort", sort_ticket)
g.add_node("billing", lambda s: {"text": "결제팀 답변"})
g.add_node("shipping", lambda s: {"text": "배송팀 답변"})
g.add_node("general", lambda s: {"text": "일반 상담 답변"})
g.add_edge(START, "sort")
g.add_conditional_edges("sort", pick_team)
for name in ["billing", "shipping", "general"]:
    g.add_edge(name, END)

app = g.compile()
print(app.invoke({"text": "배송 중인데 환불할 수 있나요?", "team": ""})["text"])

